  function parseProblemContext() {
    const path = window.location.pathname;
    let m = path.match(/\/contest\/(\d+)\/problem\/([^\/?#]+)/);
    if (m)
      return { type: "contest", cid: m[1], displayId: m[2] };
    m = path.match(/\/training\/(\d+)\/problem\/([^\/?#]+)/);
    if (m)
      return { type: "training", tid: m[1], displayId: m[2] };
    m = path.match(/\/group\/(\d+)\/problem\/([^\/?#]+)/);
    if (m)
      return { type: "problem", problemId: m[2], gid: m[1] };
    m = path.match(/\/problem[\/:]([^\/?#]+)/);
    if (m)
      return { type: "problem", problemId: m[1] };
    return null;
  }
  __name(parseProblemContext, "parseProblemContext");
